python3 - <<'PY'
import os,re
root='.'
# entity declarations in store package files, first struct declarations
ents=[]
for fn in os.listdir('store'):
 if fn.endswith('.go'):
  s=open(os.path.join('store',fn)).read()
  ents += re.findall(r'(?m)^type\s+(\w+)\s+struct\s*\{',s)
print('entities',ents)
for e in ents:
 hits={}
 for dp,ds,fs in os.walk('.'):
  if dp=='./store' or dp.startswith('./store/') or 'vendor' in dp: continue
  for f in fs:
   if f.endswith('.go'):
    p=os.path.join(dp,f); s=open(p,errors='ignore').read()
    # all qualified refs, including aliases store.
    if re.search(r'\b(?:store|storepb)\.'+re.escape(e)+r'\b',s): hits.setdefault(dp,[]).append(p)
 print(e,len(hits),sorted(hits))
PY

